using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class SeatLoggingSign {
 public static string Main(){EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");Physics.SyncTransforms();var race=Object.FindAnyObjectByType<RaceDirector>();var b=Object.FindObjectsByType<WoodlandRoute>().Single(b=>b.title.StartsWith("Abandoned"));var text=GameObject.Find("LOGGING RIDGE").transform;var board=GameObject.Find("Logging Ridge sign board").transform;var post=GameObject.Find("Logging Ridge grounded sign post").transform;bool placed=false;string result="";
 foreach(float s in new[]{8f,14f,20f}){if(placed)break;foreach(float offset in new[]{6f,-6f,8f,-8f}){var p=b.At(s,out var f);f=Vector3.ProjectOnPlane(f,Vector3.up).normalized;p+=Vector3.Cross(Vector3.up,f)*offset;float mainS=race.road.Project(p,out float d);if(d<race.road.HalfWidth(mainS)+2.5f)continue;var hits=Physics.RaycastAll(p+Vector3.up*8,Vector3.down,16,1,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.StartsWith("Ground_")).OrderBy(h=>Mathf.Abs(h.point.y-p.y)).ToArray();if(hits.Length==0)continue;p.y=hits[0].point.y;var q=Quaternion.LookRotation(f);if(Physics.OverlapBox(p+Vector3.up*2.1f,new(2.3f,.5f,.18f),q,1,QueryTriggerInteraction.Ignore).Any(c=>!c.name.StartsWith("Ground_")))continue;
 post.SetPositionAndRotation(p+Vector3.up*1.2f,q);board.SetPositionAndRotation(p+Vector3.up*2.1f,q);text.SetPositionAndRotation(p+Vector3.up*2.1f-f*.08f,q);placed=true;result=$"Logging sign: station={s}, side={offset}, main-road lateral={d:F2}, main half-width={race.road.HalfWidth(mainS):F2}; board outside both racing corridors, post base={p}";break;}}
 if(!placed)throw new Exception("No unobstructed supported shoulder sign site");EditorSceneManager.MarkSceneDirty(text.gameObject.scene);EditorSceneManager.SaveScene(text.gameObject.scene);var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Resources/VehicleGlazing.mat");mat.SetFloat("_SrcBlend",1);EditorUtility.SetDirty(mat);AssetDatabase.SaveAssets();File.AppendAllText("Docs/UndergroundPolish/grounding.txt","\n"+result);return result;
 }
}
